-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — Slovinsko II (10 tras, SI)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- Pozn.: záměrně mimo oblasti existujících SI tras (Bled/Bohinj, Logarská dolina
-- a Solčavsko, Vršič/Soča, Kras s Postojnou, Škocjanem a Lipicou).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Maribor a Pohorje – štajerské serpentiny
  delete from public.routes where name = 'Maribor a Pohorje – štajerské serpentiny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Maribor a Pohorje – štajerské serpentiny', 'Okruh kolem zeleného masivu Pohorje spojuje druhé největší slovinské město s tichými horskými silnicemi mezi smrkovými lesy a rašeliništi. Z nábřeží Lent v Mariboru se jede podél Drávy do Ruše a odtud dlouhým stoupáním plným serpentin přes Lovrenc na Pohorju až na hřebenovou Roglu v 1517 metrech. Sjezd přes Zreče a vinařské Slovenske Konjice nabídne úplně jiný svět — vinice, staré náměstí a ruiny kartuziánského kláštera v Žiče. Asfalt je většinou kvalitní, ale na hřebeni počítejte s úzkou vozovkou, lesní zvěří a o víkendech s cyklisty. Nejlepší období je květen až říjen; brzy zjara a pozdě na podzim bývá na Rogle chladno a mokro.', 'loop', 120, 240, 'medium',
     '[{"lat": 46.5576, "lng": 15.6446, "label": "Start: Maribor (Lent)"}, {"lat": 46.5389, "lng": 15.5158, "label": "Ruše"}, {"lat": 46.5406, "lng": 15.3939, "label": "Lovrenc na Pohorju"}, {"lat": 46.4531, "lng": 15.3319, "label": "Rogla"}, {"lat": 46.3369, "lng": 15.4269, "label": "Slovenske Konjice"}, {"lat": 46.3110, "lng": 15.4531, "label": "Žička kartuzija"}, {"lat": 46.5576, "lng": 15.6446, "label": "Cíl: Maribor (Lent)"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.5576,15.6446&destination=46.5576,15.6446&travelmode=driving&waypoints=46.5389,15.5158%7C46.5406,15.3939%7C46.4531,15.3319%7C46.3369,15.4269%7C46.3110,15.4531', 'https://commons.wikimedia.org/wiki/Special:FilePath/Maribor%20Lent.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Maribor%20Lent.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mariborsko%20Pohorje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lovren%C5%A1ka%20jezera.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rogla.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slovenske%20Konjice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDi%C4%8Dka%20kartuzija.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Maribor.jpg"}'::text[], '{"Maribor – Lent a Stará trta","Mariborsko Pohorje","Lovrenška jezera","Rogla (1517 m)","Slovenske Konjice","Žička kartuzija","Restaurace: Gostilna Maribor (Maribor)"}'::text[], '{"SI"}'::text[], false, 5210, 'approved');

  -- Goriška Brda a Vipavská dolina
  delete from public.routes where name = 'Goriška Brda a Vipavská dolina' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Goriška Brda a Vipavská dolina', 'Pohodová vyjížďka nejslunnějším koutem Slovinska, kde se na dohled od italské hranice vlní vinice, cypřiše a kamenné vesničky — Goriška Brda se ne nadarmo přezdívají slovinské Toskánsko. Z Nové Gorice se přes slavný Solkanský most vydáte úzkými silničkami po hřebenech Brd kolem Šmartna a zámku Dobrovo, poté se vrátíte do Vipavské doliny za bílými víny a středověkým Vipavským Križem. Silnice jsou klidné, zvlněné a plné krátkých zatáček mezi vinicemi; provoz je minimální, jen během vinobraní potkáte traktory. Ideální sezóna je duben až červen a září až říjen, kdy se sklízí hrozny a kraj voní moštem. Pozor na burju — prudký nárazový vítr, který ve Vipavské dolině umí zavřít i hlavní silnici; před jízdou zkontrolujte předpověď.', 'loop', 110, 210, 'easy',
     '[{"lat": 45.9558, "lng": 13.6486, "label": "Start: Nova Gorica"}, {"lat": 46.0064, "lng": 13.6417, "label": "Solkanský most"}, {"lat": 46.0072, "lng": 13.5411, "label": "Šmartno"}, {"lat": 45.9967, "lng": 13.5261, "label": "Dobrovo"}, {"lat": 45.8703, "lng": 13.8825, "label": "Vipavski Križ"}, {"lat": 45.8461, "lng": 13.9633, "label": "Vipava"}, {"lat": 45.8564, "lng": 13.9436, "label": "Dvorec Zemono"}, {"lat": 45.9558, "lng": 13.6486, "label": "Cíl: Nova Gorica"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.9558,13.6486&destination=45.9558,13.6486&travelmode=driving&waypoints=46.0064,13.6417%7C46.0072,13.5411%7C45.9967,13.5261%7C45.8703,13.8825%7C45.8461,13.9633%7C45.8564,13.9436', 'https://commons.wikimedia.org/wiki/Special:FilePath/Solkan%20Bridge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Solkan%20Bridge.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0martno,%20Gori%C5%A1ka%20Brda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Dobrovo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vipavski%20Kri%C5%BE.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vipava,%20Slovenia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dvorec%20Zemono.jpg"}'::text[], '{"Solkanský most","Šmartno (Goriška Brda)","Zámek Dobrovo","Vipavski Križ","Vipava (prameny řeky)","Restaurace: Gostilna pri Lojzetu (dvorec Zemono)"}'::text[], '{"SI"}'::text[], false, 5220, 'approved');

  -- Slovinská Istrie – Piran a solné pánve
  delete from public.routes where name = 'Slovinská Istrie – Piran a solné pánve' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Slovinská Istrie – Piran a solné pánve', 'Krátký, ale zážitky nabitý okruh po celém slovinském pobřeží — od přístavního Koperu přes rybářskou Izolu a útesy Strunjanu až do benátského Piranu a k solným pánvím Sečovlje. Zpáteční část vede vnitrozemím Istrie mezi olivovníky a kamennými vesnicemi ke kostelíku v Hrastovlje se slavnou freskou Tance smrti. Pobřežní silnice je malebná, ale v červenci a srpnu počítejte s hustým provozem a placeným parkováním; do Piranu je nejlepší dorazit brzy ráno. Ideální je jaro a podzim, kdy je moře fotogenické a silnice prázdné. Jízda je technicky nenáročná, jen ve vnitrozemí zpozorněte na úzkých okreskách s posypem štěrku.', 'loop', 85, 180, 'easy',
     '[{"lat": 45.5481, "lng": 13.7302, "label": "Start: Koper"}, {"lat": 45.5386, "lng": 13.6606, "label": "Izola"}, {"lat": 45.5364, "lng": 13.6069, "label": "Strunjan"}, {"lat": 45.5283, "lng": 13.5683, "label": "Piran"}, {"lat": 45.4772, "lng": 13.6083, "label": "Sečovlje"}, {"lat": 45.5069, "lng": 13.9081, "label": "Hrastovlje"}, {"lat": 45.5481, "lng": 13.7302, "label": "Cíl: Koper"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.5481,13.7302&destination=45.5481,13.7302&travelmode=driving&waypoints=45.5386,13.6606%7C45.5364,13.6069%7C45.5283,13.5683%7C45.4772,13.6083%7C45.5069,13.9081', 'https://commons.wikimedia.org/wiki/Special:FilePath/Piran.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koper.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Izola.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Strunjan%20cliff.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Piran.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Se%C4%8Doveljske%20soline.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrastovlje.jpg"}'::text[], '{"Koper – Titov trg","Izola","Strunjanské útesy","Piran – Tartiniho náměstí","Sečoveljské solné pánve","Hrastovlje – kostel sv. Trojice"}'::text[], '{"SI"}'::text[], false, 5230, 'approved');

  -- Bela krajina – údolí řeky Kolpy
  delete from public.routes where name = 'Bela krajina – údolí řeky Kolpy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Bela krajina – údolí řeky Kolpy', 'Nejjižnější kout Slovinska je krajem březových hájů, vinic a nejteplejší slovinské řeky Kolpy, která tu tvoří hranici s Chorvatskem. Okruh z Metliky vede nejprve k poutnímu areálu Tri fare a poté podél Kolpy přes Adlešiče a Vinicu — silnice kopíruje řeku, střídá krátké zatáčky a průjezdy vesničkami s vinnými sklípky. Přes Črnomelj se vrátíte kolem smaragdového pramene Krupy zpět do Metliky. Provoz je tu minimální i v sezóně, asfalt slušný, jen na okreskách u řeky počítejte s úzkou vozovkou a v létě s koupajícími se výletníky. Nejhezčí je pozdní jaro, kdy jsou březové steljniky svěže zelené, a babí léto s vinobraním.', 'loop', 85, 180, 'easy',
     '[{"lat": 45.6478, "lng": 15.3153, "label": "Start: Metlika"}, {"lat": 45.6486, "lng": 15.3308, "label": "Tri fare (Rosalnice)"}, {"lat": 45.5250, "lng": 15.3081, "label": "Adlešiči (Kolpa)"}, {"lat": 45.4614, "lng": 15.2536, "label": "Vinica"}, {"lat": 45.5711, "lng": 15.1889, "label": "Črnomelj"}, {"lat": 45.6317, "lng": 15.1592, "label": "Pramen Krupy"}, {"lat": 45.6478, "lng": 15.3153, "label": "Cíl: Metlika"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.6478,15.3153&destination=45.6478,15.3153&travelmode=driving&waypoints=45.6486,15.3308%7C45.5250,15.3081%7C45.4614,15.2536%7C45.5711,15.1889%7C45.6317,15.1592', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kolpa%20river.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Metlika.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tri%20fare,%20Rosalnice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kolpa%20river.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Crnomelj.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Izvir%20Krupe.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Metlika.jpg"}'::text[], '{"Metlika (hrad a vinařské muzeum)","Tri fare (Rosalnice)","Řeka Kolpa u Adlešičů","Črnomelj","Pramen Krupy","Restaurace: Gostilna Müller (Metlika)"}'::text[], '{"SI"}'::text[], false, 5240, 'approved');

  -- Kočevsko – země pralesů a medvědů
  delete from public.routes where name = 'Kočevsko – země pralesů a medvědů' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kočevsko – země pralesů a medvědů', 'Vyjížďka nejzalesněnějším a nejdivočejším koutem Slovinska, kde lesy pokrývají devět desetin krajiny a žije tu nejhustší populace medvěda hnědého v Evropě. Od hradu Turjak sjedete kolem rodiště slovinského písemnictví v Rašici do Ribnice, městečka proslulého výrobou dřevěného nádobí suha roba, a přes poutní kostel Nova Štifta pokračujete lesními silnicemi do Kočevje k jezeru v bývalém dole. Silnice jsou klidné a plynulé, vedou dlouhými lesními úseky — právě tady platí dvojnásob: pozor na zvěř, zvlášť za soumraku. Trasa je nenáročná a krásná od jara do podzimu; na podzim lesy Kočevského Rogu hrají všemi barvami. Medvěda z motorky nejspíš nepotkáte, ale vědomí, že tu někde je, dodává jízdě říz.', 'loop', 110, 200, 'easy',
     '[{"lat": 45.8792, "lng": 14.6089, "label": "Start: hrad Turjak"}, {"lat": 45.8494, "lng": 14.6236, "label": "Rašica"}, {"lat": 45.7392, "lng": 14.7278, "label": "Ribnica"}, {"lat": 45.7211, "lng": 14.6392, "label": "Nova Štifta"}, {"lat": 45.6431, "lng": 14.8636, "label": "Kočevje"}, {"lat": 45.8792, "lng": 14.6089, "label": "Cíl: hrad Turjak"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.8792,14.6089&destination=45.8792,14.6089&travelmode=driving&waypoints=45.8494,14.6236%7C45.7392,14.7278%7C45.7211,14.6392%7C45.6431,14.8636', 'https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Turjak.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Turjak.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Trubarjeva%20doma%C4%8Dija.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ribnica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nova%20%C5%A0tifta.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C4%8Devje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rajhenavski%20Rog.jpg"}'::text[], '{"Hrad Turjak","Trubarjeva domačija (Rašica)","Ribnica","Nova Štifta","Kočevje a Rudniško jezero","Prales Rajhenavski Rog"}'::text[], '{"SI"}'::text[], false, 5250, 'approved');

  -- Prekmurje a Prlekija – Ptuj, Jeruzalem a Vinarium
  delete from public.routes where name = 'Prekmurje a Prlekija – Ptuj, Jeruzalem a Vinarium' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Prekmurje a Prlekija – Ptuj, Jeruzalem a Vinarium', 'Pohodový okruh nejvýchodnějším Slovinskem, krajem vinic, rovin kolem řeky Mury a čápů na komínech. Z nejstaršího slovinského města Ptuje se vydáte vinařskou cestou přes kopce Prlekije do Jeruzalemu, odkud pokračujete přes Muru k plovoucímu mlýnu v Ižakovcích a k rozhledně Vinarium nad Lendavou. Zpáteční část vede přes Plečnikův kostel v Bogojině a zámecké město Murska Sobota. Silnice jsou rovné nebo zvlněné, technicky nenáročné — tohle je trasa na vychutnávání krajiny, vína (až po jízdě) a proslulého prekmurského gibanice. Nejhezčí je od jara do vinobraní; v létě počítejte s horkem, roviny Prekmurje jsou nejteplejším koutem země.', 'loop', 175, 300, 'easy',
     '[{"lat": 46.4203, "lng": 15.8700, "label": "Start: Ptuj"}, {"lat": 46.4072, "lng": 16.1544, "label": "Ormož"}, {"lat": 46.4761, "lng": 16.1878, "label": "Jeruzalem"}, {"lat": 46.5761, "lng": 16.2314, "label": "Ižakovci (mlýn na Muře)"}, {"lat": 46.5672, "lng": 16.4661, "label": "Lendava (Vinarium)"}, {"lat": 46.6739, "lng": 16.2703, "label": "Bogojina"}, {"lat": 46.6586, "lng": 16.1614, "label": "Murska Sobota"}, {"lat": 46.4203, "lng": 15.8700, "label": "Cíl: Ptuj"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.4203,15.8700&destination=46.4203,15.8700&travelmode=driving&waypoints=46.4072,16.1544%7C46.4761,16.1878%7C46.5761,16.2314%7C46.5672,16.4661%7C46.6739,16.2703%7C46.6586,16.1614', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ptuj%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ptuj%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jeruzalem,%20Slovenia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Babi%C4%8Dev%20mlin.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vinarium%20Lendava.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bogojina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Murska%20Sobota.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Murska%20Sobota.jpg"}'::text[], '{"Ptuj – hrad nad Drávou","Jeruzalem – vinice Prlekije","Plovoucí mlýn na Muře (Ižakovci)","Rozhledna Vinarium (Lendava)","Bogojina – Plečnikův kostel","Murska Sobota","Restaurace: Gostilna Rajh (Bakovci)"}'::text[], '{"SI"}'::text[], false, 5260, 'approved');

  -- Škofjeloško hribovje a kostelík Jamnik
  delete from public.routes where name = 'Škofjeloško hribovje a kostelík Jamnik' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Škofjeloško hribovje a kostelík Jamnik', 'Kopcovitý okruh mezi Škofjou Lokou a Sorišskou planinou prověří chuť do zatáček — úzké silničky Škofjeloského a Selského pohoří šplhají na hřebeny, padají do údolí a servírují výhledy na Julské Alpy i Kamnicko-Savinjské štíty. Ze středověké Škofje Loky vystoupáte ke kovářské vesnici Kropa a k osamělému kostelíku na hřebeni Jamnik, jednomu z nejfotografovanějších míst Slovinska. Přes památné Dražgoše sjedete do Železniků a Selskou dolinou pokračujete do malované vesnice Sorica a na sedlo Soriška planina. Vozovka je místy úzká, s ostrými slepými zatáčkami a v zimě neudržovaná — trasa je nejlepší od května do října. Odměnou za soustředěnou jízdu jsou prázdné silnice a atmosféra starého horského Kraňska.', 'loop', 100, 220, 'medium',
     '[{"lat": 46.1656, "lng": 14.3064, "label": "Start: Škofja Loka"}, {"lat": 46.2933, "lng": 14.2069, "label": "Kropa"}, {"lat": 46.2775, "lng": 14.1836, "label": "Jamnik"}, {"lat": 46.2467, "lng": 14.1653, "label": "Dražgoše"}, {"lat": 46.2258, "lng": 14.1697, "label": "Železniki"}, {"lat": 46.2189, "lng": 14.0269, "label": "Sorica"}, {"lat": 46.2094, "lng": 14.0119, "label": "Soriška planina"}, {"lat": 46.1656, "lng": 14.3064, "label": "Cíl: Škofja Loka"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.1656,14.3064&destination=46.1656,14.3064&travelmode=driving&waypoints=46.2933,14.2069%7C46.2775,14.1836%7C46.2467,14.1653%7C46.2258,14.1697%7C46.2189,14.0269%7C46.2094,14.0119', 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0kofja%20Loka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0kofja%20Loka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kropa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jamnik%20church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dra%C5%BEgo%C5%A1e.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDelezniki.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sorica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sori%C5%A1ka%20planina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0kofja%20Loka.jpg"}'::text[], '{"Škofja Loka","Kropa – kovářská vesnice","Kostelík Jamnik","Dražgoše","Železniki","Sorica","Soriška planina","Restaurace: Gostilna Kašča (Škofja Loka)"}'::text[], '{"SI"}'::text[], false, 5270, 'approved');

  -- Dolenjska – údolí řeky Krky
  delete from public.routes where name = 'Dolenjska – údolí řeky Krky' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Dolenjska – údolí řeky Krky', 'Putování podél nejdelší čistě slovinské řeky od cisterciáckého kláštera Stična až do Kostanjevice na Krki, městečka na říčním ostrově. Krka teče zeleným údolím přes travertinové jezy a silnice ji věrně sleduje — jízda je plynulá, s výhledy na hrady, vrbové břehy a vinice Dolenjska, kde zraje lehké růžové víno cviček. Cestou minete mohutný hrad v Žužemberku, projedete krajským Novým mestem a kolem pohádkového vodního hradu Otočec dorazíte ke kartuziánskému klášteru Pleterje. Trasa je nenáročná, vhodná i pro méně zkušené jezdce a krásná od jara do podzimu. V létě přibývá cyklistů a u jezů se koupou místní, tak u řeky zpomalte a vychutnejte si tempo Dolenjska.', 'poi', 95, 180, 'easy',
     '[{"lat": 45.9575, "lng": 14.8069, "label": "Start: klášter Stična"}, {"lat": 45.8336, "lng": 14.9292, "label": "Žužemberk"}, {"lat": 45.8036, "lng": 15.1689, "label": "Novo mesto"}, {"lat": 45.8386, "lng": 15.2247, "label": "Otočec"}, {"lat": 45.8206, "lng": 15.3372, "label": "Pleterje"}, {"lat": 45.8461, "lng": 15.4231, "label": "Cíl: Kostanjevica na Krki"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.9575,14.8069&destination=45.8461,15.4231&travelmode=driving&waypoints=45.8336,14.9292%7C45.8036,15.1689%7C45.8386,15.2247%7C45.8206,15.3372', 'https://commons.wikimedia.org/wiki/Special:FilePath/Oto%C4%8Dec%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sti%C4%8Dna%20Abbey.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDu%C5%BEemberk%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Novo%20mesto.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oto%C4%8Dec%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kartuzija%20Pleterje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostanjevica%20na%20Krki.jpg"}'::text[], '{"Klášter Stična","Hrad Žužemberk","Novo mesto – Glavni trg","Hrad Otočec","Kartuziánský klášter Pleterje","Kostanjevica na Krki"}'::text[], '{"SI"}'::text[], false, 5280, 'approved');

  -- Idrija a Cerkljansko – rtuť, čipky a nemocnice Franja
  delete from public.routes where name = 'Idrija a Cerkljansko – rtuť, čipky a nemocnice Franja' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Idrija a Cerkljansko – rtuť, čipky a nemocnice Franja', 'Technicky zábavný okruh zvrásněnou krajinou mezi Logatcem, Idrijí a Cerknem, kde se silnice bez ustání kroutí přes hřebeny a hluboká údolí říček Idrijca a Sora. Hlavním magnetem je Idrija — město rtuťového dolu zapsané v UNESCO, proslulé paličkovanou krajkou a knedlíčky žlikrofi. Za Idrijí se zastavíte u tajemného krasového Divjeho jezera, přes Cerkno dojedete k partyzánské nemocnici Franja ukryté v soutěsce a zpět se vrátíte přes krajkářské městečko Žiri. Silnice jsou úzké, samá zatáčka a místy zvlněný asfalt — přesně to, co baví; kamionů tu potkáte minimum. Nejlepší období je květen až říjen, po dešti pozor na vlhké lesní úseky a padané kamení.', 'loop', 115, 230, 'medium',
     '[{"lat": 45.9144, "lng": 14.2258, "label": "Start: Logatec"}, {"lat": 46.0022, "lng": 14.0272, "label": "Idrija"}, {"lat": 45.9906, "lng": 14.0189, "label": "Divje jezero"}, {"lat": 46.1253, "lng": 13.9814, "label": "Cerkno"}, {"lat": 46.1461, "lng": 14.0072, "label": "Nemocnice Franja"}, {"lat": 46.0442, "lng": 14.1097, "label": "Žiri"}, {"lat": 45.9144, "lng": 14.2258, "label": "Cíl: Logatec"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.9144,14.2258&destination=45.9144,14.2258&travelmode=driving&waypoints=46.0022,14.0272%7C45.9906,14.0189%7C46.1253,13.9814%7C46.1461,14.0072%7C46.0442,14.1097', 'https://commons.wikimedia.org/wiki/Special:FilePath/Idrija.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Idrija.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Gewerkenegg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Divje%20jezero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerkno.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Partizanska%20bolnica%20Franja.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDiri.jpg"}'::text[], '{"Idrija – rtuťový důl UNESCO","Hrad Gewerkenegg","Divje jezero","Cerkno","Partyzánská nemocnice Franja","Žiri"}'::text[], '{"SI"}'::text[], false, 5290, 'approved');

  -- Údolí Savinje – Celje, Laško a Žalec
  delete from public.routes where name = 'Údolí Savinje – Celje, Laško a Žalec' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolí Savinje – Celje, Laško a Žalec', 'Nenáročný okruh dolním Posavinjem spojuje knížecí Celje s pivním Laškem a chmelařským Žalcem — krajem, kterému se říká údolí zeleného zlata. Od největšího středověkého hradu ve Slovinsku sjedete soutěskou Savinje do lázeňského Laška, kde se od roku 1825 vaří nejznámější slovinské pivo. Zpět přes Celje pokračujete do Šempeteru k římské nekropoli a do Žalce, kde z veřejné fontány teče šest druhů piva z okolního chmele. Silnice podél Savinje je svižná a malebná, mezi chmelnicemi se jede po rovinách — ideální odpolední vyjížďka bez technických nástrah. Trasa je krásná od jara do podzimu, nejzajímavější v září, kdy vrcholí sklizeň chmele; pivní ochutnávky si nechte až po odstavení motorky.', 'loop', 70, 160, 'easy',
     '[{"lat": 46.2361, "lng": 15.2675, "label": "Start: Celje"}, {"lat": 46.2197, "lng": 15.2753, "label": "Stari grad Celje"}, {"lat": 46.1544, "lng": 15.2364, "label": "Laško"}, {"lat": 46.2564, "lng": 15.1214, "label": "Šempeter"}, {"lat": 46.2514, "lng": 15.1647, "label": "Žalec"}, {"lat": 46.2708, "lng": 15.2469, "label": "Šmartinsko jezero"}, {"lat": 46.2361, "lng": 15.2675, "label": "Cíl: Celje"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.2361,15.2675&destination=46.2361,15.2675&travelmode=driving&waypoints=46.2197,15.2753%7C46.1544,15.2364%7C46.2564,15.1214%7C46.2514,15.1647%7C46.2708,15.2469', 'https://commons.wikimedia.org/wiki/Special:FilePath/Celje%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Celje%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/La%C5%A1ko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rimska%20nekropola%20%C5%A0empeter.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fontana%20piv%20Zeleno%20zlato.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0martinsko%20jezero.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Celje.jpg"}'::text[], '{"Celjský hrad (Stari grad)","Laško","Římská nekropole Šempeter","Žalec – Fontána piv","Šmartinsko jezero","Restaurace: Stari Pisker (Celje)"}'::text[], '{"SI"}'::text[], false, 5300, 'approved');

