  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Maribor – Lent a Stará trta', 'Historické nábřeží Lent na břehu Drávy je nejstarší částí Mariboru a roste tu Stará trta — přes čtyři sta let stará vinná réva, zapsaná v Guinnessově knize jako nejstarší plodící réva světa. Kolem Domu Staré trty najdete kavárny, vinotéky a příjemnou promenádu. Ideální místo na kávu před vyjížďkou a fotku motorky u řeky.', 46.5576, 15.6446, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maribor%20Lent.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Maribor%20Lent.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stara%20trta.jpg"}'::text[], 0),
    (v_route, 'Mariborsko Pohorje', 'Lyžařské a turistické středisko na svazích přímo nad Mariborem, kam z městské čtvrti Radvanje vyjíždí kabinková lanovka. Od spodní stanice se silnice stáčí do prvních serpentin a nahoře se otevírají výhledy na město a údolí Drávy. V zimě se tu jezdí slalom Zlatá liška, v létě je to nástupiště do lesů Pohorje.', 46.5279, 15.6013, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mariborsko%20Pohorje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mariborsko%20Pohorje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pohorje.jpg"}'::text[], 1),
    (v_route, 'Lovrenška jezera', 'Největší vrchovištní rašeliniště ve Slovinsku s dvaceti temnými jezírky, schované v sedle mezi Roglou a Lovrencem. Od silnice k němu vede dřevěný chodník a vyhlídková věž, ze které přehlédnete celou náhorní plošinu. Krátká procházka je příjemným protažením nohou uprostřed horské etapy okruhu.', 46.4864, 15.4064, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lovren%C5%A1ka%20jezera.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lovren%C5%A1ka%20jezera.jpg"}'::text[], 2),
    (v_route, 'Rogla (1517 m)', 'Nejvyšší bod okruhu — horské středisko na zalesněném hřebeni Pohorje s rozhlednou, chatami a stezkou v korunách stromů. Silnice sem stoupá z obou stran dlouhými, pravidelnými serpentinami s výborným rytmem jízdy. Za jasného počasí dohlédnete až na Kamnicko-Savinjské Alpy; i v létě si sem vezměte teplejší vrstvu.', 46.4531, 15.3319, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rogla.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rogla.jpg"}'::text[], 3),
    (v_route, 'Slovenske Konjice', 'Malebné vinařské městečko pod horou Konjiška gora, jehož protáhlé staré náměstí lemují měšťanské domy s pestrými fasádami a potok tekoucí středem ulice. Okolní svahy pokrývají vinice Štajerska a v místních vinotékách ochutnáte bílá vína z okolí. Příjemná zastávka po sjezdu z hor.', 46.3369, 15.4269, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slovenske%20Konjice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slovenske%20Konjice.jpg"}'::text[], 4),
    (v_route, 'Žička kartuzija', 'Působivé ruiny kartuziánského kláštera z 12. století, ukryté v tichém údolí sv. Jana Křtitele u Žiče. Byl to jeden z prvních kartuziánských klášterů mimo Francii a dnes tu vedle gotických zdí funguje i jedna z nejstarších lékáren v Evropě a bylinková zahrada. Ke klášteru vede úzká slepá silnička údolím — krátká odbočka, která stojí za to.', 46.3110, 15.4531, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDi%C4%8Dka%20kartuzija.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDi%C4%8Dka%20kartuzija.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Gostilna Maribor (Maribor)', 'Výborně hodnocená restaurace v historickém centru Mariboru, která moderně servíruje štajerskou klasiku — od hovězího vývaru s domácími nudlemi po pohorský hrnec a místní vína. Poctivé porce a milá obsluha z ní dělají ideální tečku za okruhem. V sezóně se hodí rezervace.', 46.5586, 15.6450, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maribor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Maribor.jpg"}'::text[], 6);
