  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Solkanský most', 'Železniční most přes smaragdovou Sočiu u Solkanu má hlavní oblouk o rozpětí 85 metrů — největší kamenný obloukový most na železnici na světě. Nejlepší výhled je z vyhlídky u silnice na levém břehu, kde se dá pohodlně zastavit. Kombinace tyrkysové řeky a bílého kamene je jedno z nejfotogeničtějších míst Primorska.', 46.0064, 13.6417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Solkan%20Bridge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Solkan%20Bridge.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Solkanski%20most.jpg"}'::text[], 0),
    (v_route, 'Šmartno (Goriška Brda)', 'Opevněná středověká vesnice na vrcholu kopce uprostřed Brd, obehnaná hradbami s věžemi a považovaná za nejkrásnější vesnici kraje. Kamenné uličky ukrývají galerie, vinotéky a výhledy na moře vinic; kousek odtud stojí rozhledna Gonjače s panoramatem od Alp po Jadran. Povinná zastávka každé vyjížďky po Brdech.', 46.0072, 13.5411, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0martno,%20Gori%C5%A1ka%20Brda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0martno,%20Gori%C5%A1ka%20Brda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gori%C5%A1ka%20brda.jpg"}'::text[], 1),
    (v_route, 'Zámek Dobrovo', 'Renesanční zámek ze 17. století uprostřed vinic je centrem vinařství Goriška Brda — v jeho sklepích sídlí vinotéka místního družstva Klet Brda, největšího producenta vína v zemi. Ochutnáte tu rebulu i další místní odrůdy (řidič samozřejmě jen degustačně přivoní) a prohlédnete si zámecké sály. Kolem zámku se rozprostírají nejslavnější vinohrady Slovinska.', 45.9967, 13.5261, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Dobrovo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Dobrovo.jpg"}'::text[], 2),
    (v_route, 'Vipavski Križ', 'Drobné opevněné městečko na návrší uprostřed Vipavské doliny, celé památkově chráněné — hradby, kapucínský klášter a kamenné domy se od středověku téměř nezměnily. Z hradeb je krásný výhled na dolinu rámovanou plošinou Trnovského lesa. Patří k nejmenším a nejpůvabnějším historickým sídlům v zemi.', 45.8703, 13.8825, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vipavski%20Kri%C5%BE.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vipavski%20Kri%C5%BE.jpg"}'::text[], 3),
    (v_route, 'Vipava (prameny řeky)', 'Městečko Vipava vyrostlo přímo kolem pramenů stejnojmenné řeky, která tu vyvěrá hned několika krasovými výtoky pod skalní stěnou — říká se jí proto slovinské Benátky. Přes ramena řeky se klene řada kamenných můstků a v okolí sídlí známá vinařství. Příjemné místo na procházku a zmrzlinu ve stínu platanů.', 45.8461, 13.9633, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vipava,%20Slovenia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vipava,%20Slovenia.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Gostilna pri Lojzetu (dvorec Zemono)', 'Legendární restaurace šéfkuchaře Tomaže Kavčiče v barokním letohrádku Zemono nad Vipavskou dolinou, oceněná michelinskou hvězdou. Servíruje hravou degustační kuchyni z místních surovin s výhledem na vinice; kdo chce jen lehčí oběd, najde v okolí Vipavy i neformálnější podniky. Zážitková tečka okruhu — rezervace nutná.', 45.8564, 13.9436, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dvorec%20Zemono.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dvorec%20Zemono.jpg"}'::text[], 5);
