  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Koper – Titov trg', 'Historické jádro největšího slovinského přístavu vyrostlo pod benátskou správou a Titovo náměstí s Pretorským palácem, loggií a katedrálou je toho nejlepší ukázkou. Ze zvonice katedrály je výhled na celý Terstský záliv. Motorku pohodlně odstavíte u nábřeží a centrum projdete pěšky za půl hodiny.', 45.5481, 13.7302, 'https://commons.wikimedia.org/wiki/Special:FilePath/Koper.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koper.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Titov%20trg,%20Koper.jpg"}'::text[], 0),
    (v_route, 'Izola', 'Bývalý rybářský ostrov, dnes půvabné městečko s pestrobarevnými domy namačkanými kolem přístavu plného lodí. Uličky voní grilovanými sardinkami a na rozdíl od Piranu si Izola drží civilnější, místní atmosféru. Ideální zastávka na ranní kávu na molu.', 45.5386, 13.6606, 'https://commons.wikimedia.org/wiki/Special:FilePath/Izola.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Izola.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Izola,%20Slovenia.jpg"}'::text[], 1),
    (v_route, 'Strunjanské útesy', 'Nejvyšší flyšové útesy na celém Jadranu — osmdesátimetrová stěna Strunjanského poloostrova spadá kolmo do moře v chráněné přírodní rezervaci. Od silnice vede krátká stezka na vyhlídku nad zátokou Mesečev zaliv, jednou z nejzachovalejších částí slovinského pobřeží. Krásné místo na fotku, koupání je dole v zátoce.', 45.5364, 13.6069, 'https://commons.wikimedia.org/wiki/Special:FilePath/Strunjan%20cliff.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Strunjan%20cliff.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Strunjan.jpg"}'::text[], 2),
    (v_route, 'Piran – Tartiniho náměstí', 'Nejkrásnější město slovinského pobřeží: benátské paláce, oválné Tartiniho náměstí a špička poloostrova s majákem, kde se uličky sbíhají k moři. Vyplatí se vystoupat ke kostelu sv. Jiří a hradbám — výhled na červené střechy a záliv je ikonou celé země. Do centra motorky nesmí, parkuje se u vjezdu do města.', 45.5283, 13.5683, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piran.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piran.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tartinijev%20trg,%20Piran.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Fritolin pri Cantini (Piran)', 'Kultovní neformální podnik na náměstíčku za piranským přístavem, kde si smažené i grilované ryby objednáte u okénka a sníte je u stolků pod slunečníky. Čerstvé kalamáry, sardinky a rybí polévka za férové ceny — přesně to, co k Jadranu patří. Ve špičce počítejte s frontou, stojí za to.', 45.5278, 13.5697, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piran.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piran.jpg"}'::text[], 4),
    (v_route, 'Sečoveljské solné pánve', 'Rozlehlá krajina solných polí u ústí řeky Dragonji, kde se sůl sbírá ručně stejným způsobem už sedm set let. Krajinný park je rájem vodních ptáků a v muzeu solinářství uvidíte domky solinářů i dřevěné nástroje. Květ soli ze Sečovlje je vyhlášená pochoutka a hezký suvenýr do kufru motorky.', 45.4772, 13.6083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Se%C4%8Doveljske%20soline.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Se%C4%8Doveljske%20soline.jpg"}'::text[], 5),
    (v_route, 'Hrastovlje – kostel sv. Trojice', 'Drobný románský kostelík obehnaný protitureckou zdí ukrývá nejslavnější středověkou fresku Slovinska — Tanec smrti z roku 1490, na němž kostlivci odvádějí k hrobu papeže i sedláka. Kostel stojí nad kamennou vesničkou na okraji istrijského vnitrozemí, kam vede klidná okreska mezi olivovníky. Malé, ale nezapomenutelné místo.', 45.5069, 13.9081, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrastovlje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrastovlje.jpg"}'::text[], 6);
