  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Metlika (hrad a vinařské muzeum)', 'Pohraniční městečko s trojicí náměstí a renesančním hradem, v němž sídlí muzeum Bela krajiny a slovinské vinařské muzeum. Metlika je centrem vinorodého kraje — právě odtud pochází lehké červené víno metliška črnina. Příjemný start okruhu s kavárnami na náměstí Mestni trg.', 45.6478, 15.3153, 'https://commons.wikimedia.org/wiki/Special:FilePath/Metlika.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Metlika.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Metlika.jpg"}'::text[], 0),
    (v_route, 'Tri fare (Rosalnice)', 'Unikátní poutní areál na kraji vesnice Rosalnice — tři gotické kostely stojící těsně vedle sebe na jednom hřbitově za společnou zdí. Podobný soubor nemá ve střední Evropě obdoby a jeho původ sahá až k templářům. Klidné, téměř mystické místo pět minut od Metliky.', 45.6486, 15.3308, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tri%20fare,%20Rosalnice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tri%20fare,%20Rosalnice.jpg"}'::text[], 1),
    (v_route, 'Řeka Kolpa u Adlešičů', 'Nejteplejší slovinská řeka se u Adlešičů líně vine mezi jezy starých mlýnů a v létě se v ní dá výborně koupat. Silnice podél Kolpy patří k nejmalebnějším v kraji — z jedné strany řeka a chorvatský břeh, z druhé vinice a březové háje. U jezů je řada travnatých plácků, kde se dá zastavit a smočit nohy.', 45.5250, 15.3081, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kolpa%20river.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kolpa%20river.jpg"}'::text[], 2),
    (v_route, 'Črnomelj', 'Hlavní město Bela krajiny leží na skalním ostrohu obtékaném řekami Lahinja a Dobličica. Staré jádro s hradem a kostelem obejdete za chvíli; město je známé folklorním festivalem Jurjevanje, nejstarším ve Slovinsku, který slaví zelené jaro. Dobré místo na doplnění paliva a kávu.', 45.5711, 15.1889, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Crnomelj.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Crnomelj.jpg"}'::text[], 3),
    (v_route, 'Pramen Krupy', 'Řeka Krupa vyvěrá v plné síle přímo z třicetimetrové skalní stěny — smaragdově zelená hladina pod převisem patří k nejkrásnějším krasovým pramenům v zemi. Od parkoviště u vesnice Krupa je to k prameni pár minut pěšky. V podzemí zdejšího krasu žije vzácný jeskynní mlok macarát.', 45.6317, 15.1592, 'https://commons.wikimedia.org/wiki/Special:FilePath/Izvir%20Krupe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Izvir%20Krupe.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Gostilna Müller (Metlika)', 'Rodinná gostilna na kraji Metliky s dlouhou tradicí a výborným hodnocením, proslulá belokrajinskou kuchyní — jehněčím a prasátkem z pece, domácí poviticí a plackou belokranjska pogača. K jídlu nalévají místní vína z okolních vinic. Ideální závěr okruhu.', 45.6494, 15.3122, 'https://commons.wikimedia.org/wiki/Special:FilePath/Metlika.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Metlika.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Turjak', 'Mohutný hrad rodu Auerspergů na skále nad údolím střeží cestu na Kočevsko už od 13. století. Prohlédnete si rytířský sál, kapli a hradby s výhledem do kraje; hrad hrál důležitou roli i za druhé světové války. Prostorné parkoviště pod hradem je pohodlný start okruhu.', 45.8792, 14.6089, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Turjak.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Turjak.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Turjak%20Castle.jpg"}'::text[], 0),
    (v_route, 'Trubarjeva domačija (Rašica)', 'Rodný statek Primože Trubara, autora první slovinsky tištěné knihy, je dnes malebným skanzenem s mlýnem, pilou a expozicí o počátcích slovinského písemnictví. Areál leží u potoka pod vesnicí Rašica hned u silnice. Krátká zastávka, která dává jízdě přes tenhle tichý kraj historický kontext.', 45.8494, 14.6236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trubarjeva%20doma%C4%8Dija.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trubarjeva%20doma%C4%8Dija.jpg"}'::text[], 1),
    (v_route, 'Ribnica', 'Městečko proslulé po staletí výrobou suché roby — dřevěného nádobí, sít a košíků, které ribničtí podomní obchodníci roznášeli po celé Evropě. V hradu u řeky Bistrice sídlí muzeum řemesel a v obchůdcích koupíte originální dřevěné suvenýry. Živé náměstí s kavárnami zve na zastávku.', 45.7392, 14.7278, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ribnica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ribnica.jpg"}'::text[], 2),
    (v_route, 'Nova Štifta', 'Barokní poutní kostel Nanebevzetí Panny Marie z poloviny 17. století patří k nejkrásnějším ve Slovinsku — osmiboká stavba s arkádami stojí osaměle na svahu nad ribnickým údolím vedle mohutné staleté lípy. K poutnímu místu vede klidná silnička s pěkným výhledem zpět do kraje. Ideální krátká odbočka z Ribnice.', 45.7211, 14.6392, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nova%20%C5%A0tifta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nova%20%C5%A0tifta.jpg"}'::text[], 3),
    (v_route, 'Kočevje a Rudniško jezero', 'Centrum Kočevska leží uprostřed nekonečných lesů a jeho jezero vzniklé zatopením hnědouhelného dolu má sytě modrou barvu a promenádu s plážemi. Město bylo po staletí domovem kočevských Němců a jeho pohnutou historii přibližuje regionální muzeum. U jezera se dobře odpočívá s výhledem na hladinu a lesnaté hřebeny Rogu.', 45.6431, 14.8636, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C4%8Devje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C4%8Devje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rudni%C5%A1ko%20jezero.jpg"}'::text[], 4),
    (v_route, 'Prales Rajhenavski Rog', 'V hřebenech Kočevského Rogu se dochoval jeden z posledních pravých pralesů Evropy — les, do kterého člověk nikdy nezasáhl sekerou, s jedlemi a buky vysokými přes čtyřicet metrů. K okraji rezervace vede z Kočevje zpevněná lesní cesta a naučná stezka; do samotného pralesa se nevstupuje, obdivuje se z hranice. Tady pochopíte, proč se Kočevsku říká slovinská divočina.', 45.6606, 14.9761, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rajhenavski%20Rog.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rajhenavski%20Rog.jpg"}'::text[], 5);
