  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ptuj – hrad nad Drávou', 'Nejstarší doložené město Slovinska s římskými kořeny, jehož panorama s hradem nad Drávou patří k nejfotografovanějším pohledům země. Dlážděné uličky, věž městského kostela a vinné sklepy Ptujska klet lákají k procházce; hradní muzeum vystavuje masky kurentů, tradičních masopustních postav zapsaných v UNESCO. Skvělý start i cíl okruhu.', 46.4203, 15.8700, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ptuj%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ptuj%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ptuj.jpg"}'::text[], 0),
    (v_route, 'Jeruzalem – vinice Prlekije', 'Vesnička na hřebeni vinorodých kopců, pojmenovaná podle křižáků, kterým zdejší víno připomnělo Svatou zemi. Vinařská cesta z Ormože do Jeruzalemu je jedna z nejkrásnějších v zemi — samý výhled, vinohrad a klaněnec. Nahoře čekají vinotéky, kaple a panoráma až k maďarské hranici.', 46.4761, 16.1878, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jeruzalem,%20Slovenia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jeruzalem,%20Slovenia.jpg"}'::text[], 1),
    (v_route, 'Plovoucí mlýn na Muře (Ižakovci)', 'Na Ostrově lásky u Ižakovců kotví věrná replika plovoucího mlýna, jaké kdysi po desítkách mlely obilí přímo na proudu řeky Mury. Přes řeku vás převeze lanový přívoz brod a v mlýně koupíte čerstvě semletou mouku. Idylické místo na piknik ve stínu vrb u nejvodnatější slovinské řeky.', 46.5761, 16.2314, 'https://commons.wikimedia.org/wiki/Special:FilePath/Babi%C4%8Dev%20mlin.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Babi%C4%8Dev%20mlin.jpg"}'::text[], 2),
    (v_route, 'Rozhledna Vinarium (Lendava)', 'Třiapadesát metrů vysoká vyhlídková věž mezi vinicemi Lendavských goric nabízí výhled do čtyř zemí najednou — Slovinska, Maďarska, Chorvatska a Rakouska. Nahoru vyjedete výtahem nebo po 240 schodech; dole se ochutnává místní specialita bograč, kotlíkový guláš na čtyři druhy masa. Nejnavštěvovanější atrakce Prekmurje.', 46.5672, 16.4661, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vinarium%20Lendava.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vinarium%20Lendava.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lendava.jpg"}'::text[], 3),
    (v_route, 'Bogojina – Plečnikův kostel', 'Kostel Nanebevstoupení Páně v Bogojině je venkovským mistrovským dílem architekta Jože Plečnika — bílá rotunda s válcovou věží, uvnitř strop zdobený prekmurskou keramikou. Stojí na návrší nad vesnicí a je vidět z daleka přes roviny. Krátká, ale architektonicky nejcennější zastávka okruhu.', 46.6739, 16.2703, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bogojina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bogojina.jpg"}'::text[], 4),
    (v_route, 'Murska Sobota', 'Hlavní město Prekmurje s renesančním zámkem uprostřed rozlehlého městského parku, v němž sídlí regionální muzeum s expozicí o životě na rovině kolem Mury. Město je příjemné na krátkou procházku a kávu; v okolních vesnicích hnízdí na komínech čápi, symbol celého kraje.', 46.6586, 16.1614, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Murska%20Sobota.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Murska%20Sobota.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Murska%20Sobota.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Gostilna Rajh (Bakovci)', 'Rodinná restaurace v Bakovcích u Murske Soboty patří k nejlepším ve Slovinsku a je vyhlášenou svatyní prekmurské kuchyně — bograč, dödöle (bramborové noky se škvarky) a pravá prekmurska gibanica podle receptu babičky Rajhových. Doporučená michelinským průvodcem, přesto s poctivými venkovskými porcemi. Rezervace se vyplatí.', 46.6203, 16.1339, 'https://commons.wikimedia.org/wiki/Special:FilePath/Murska%20Sobota.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Murska%20Sobota.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Škofja Loka', 'Nejzachovalejší středověké město Slovinska s hradem, kamenným Kapucínským mostem a náměstím lemovaným malovanými měšťanskými domy. Tisíc let historie biskupského panství je tu vidět na každém kroku a hradní muzeum nabízí výhled na staré střechy. Ideální výchozí bod okruhu s kavárnami na Mestnem trgu.', 46.1656, 14.3064, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0kofja%20Loka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0kofja%20Loka.jpg"}'::text[], 0),
    (v_route, 'Kropa – kovářská vesnice', 'Úzké údolí potoka Kroparica po staletí žilo kovářstvím — vodní kladiva tu kula hřebíky pro půl Evropy a dnes řemeslo připomíná kovářské muzeum a zdobené kované detaily na každém domě. Vesnice sevřená mezi skalami působí, jako by se v ní zastavil čas. Odtud stoupá úzká silnička přímo na hřeben k Jamniku.', 46.2933, 14.2069, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kropa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kropa.jpg"}'::text[], 1),
    (v_route, 'Kostelík Jamnik', 'Kostelík sv. Primože a Felicijana stojí osaměle na travnatém hřebeni nad údolím a s panoramatem Julských Alp v zádech patří k nejfotografovanějším motivům Slovinska. Za úsvitu a při inverzích, kdy z moře mlhy trčí jen kostelík a hory, sem míří fotografové z celého světa. Motorku necháte u silnice a k vrcholu dojdete pár minut pěšky.', 46.2775, 14.1836, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jamnik%20church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jamnik%20church.jpg"}'::text[], 2),
    (v_route, 'Dražgoše', 'Horská vesnice proslulá bitvou z ledna 1942, kdy se tu partyzáni jako první v okupované Evropě postavili německé přesile v otevřeném boji; památník nad vesnicí připomíná její tragickou daň. Dnes je to tiché místo s dalekým výhledem do hor. Silnice od Jamniku k Dražgošam je jedna z nejhezčích hřebenovek v okolí.', 46.2467, 14.1653, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dra%C5%BEgo%C5%A1e.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dra%C5%BEgo%C5%A1e.jpg"}'::text[], 3),
    (v_route, 'Železniki', 'Podlouhlé městečko na dně Selské doliny se šest set let živilo železářstvím — dochovala se tu jediná zachovalá vysoká pec ve Slovinsku a muzeum s expozicí slavné železnikarské paličkované krajky. Domy tu stojí namačkané mezi řekou a svahy, což dává městečku nezaměnitelný ráz. Dobré místo na doplnění paliva před horskou etapou.', 46.2258, 14.1697, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDelezniki.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDelezniki.jpg"}'::text[], 4),
    (v_route, 'Sorica', 'Malovaná horská vesnice na slunečné terase nad Selskou dolinou, rodiště impresionisty Ivana Grohara, jehož ateliér si tu můžete prohlédnout. Vesnici založili ve středověku osadníci z Tyrolska a alpský ráz si drží dodnes. Ze silnice nad vesnicí je jeden z nejhezčích výhledů celé trasy.', 46.2189, 14.0269, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sorica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sorica.jpg"}'::text[], 5),
    (v_route, 'Soriška planina', 'Horské sedlo v 1300 metrech mezi Selskou dolinou a Baškou grapou, v zimě malé lyžařské středisko, v létě rozhledové pastviny s panoramatem od Triglavu po Ratitovec. Nejvyšší bod okruhu — ideální místo na fotku motorky s horami v pozadí. Sjezd zpět do doliny je dlouhá řada serpentin, tak s rozvahou.', 46.2094, 14.0119, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sori%C5%A1ka%20planina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sori%C5%A1ka%20planina.jpg"}'::text[], 6),
    (v_route, 'Restaurace: Gostilna Kašča (Škofja Loka)', 'Restaurace a vinotéka v šest set let staré kamenné sýpce na Spodním trgu ve Škofje Loce, jedna z nejlépe hodnocených v okolí. Pod gotickými klenbami servírují loške štruklje, zvěřinu i steaky a k tomu dobrý výběr slovinských vín. Stylová tečka za okruhem po starém Kraňsku.', 46.1647, 14.3078, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0kofja%20Loka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0kofja%20Loka.jpg"}'::text[], 7);
  insert into public.routes
