  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Klášter Stična', 'Nejstarší klášter ve Slovinsku, založený cisterciáky roku 1136 a dodnes obývaný mnichy. Za mohutnými zdmi se skrývá románská bazilika, gotický ambit a muzeum křesťanství; klášterní obchůdek prodává proslulé bylinné čaje patera Ašiče. Klidné místo na start jízdy údolím Krky.', 45.9575, 14.8069, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sti%C4%8Dna%20Abbey.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sti%C4%8Dna%20Abbey.jpg"}'::text[], 0),
    (v_route, 'Hrad Žužemberk', 'Jedna z nejmalebnějších pevností v zemi — hrad s mohutnými okrouhlými baštami stojí na terase přímo nad travertinovými jezy Krky uprostřed městečka. Přes léto se na nádvoří konají trhy a koncerty, z hradeb je krásný pohled na řeku. Pod hradem se dá zastavit hned u vody.', 45.8336, 14.9292, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDu%C5%BEemberk%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDu%C5%BEemberk%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20%C5%BDu%C5%BEemberk.jpg"}'::text[], 1),
    (v_route, 'Novo mesto – Glavni trg', 'Hlavní město Dolenjska leží v dramatickém meandru Krky a jeho obloukovité Hlavní náměstí s podloubími patří k nejhezčím ve Slovinsku. Kapitulní kostel sv. Mikuláše ukrývá obraz od Tintoretta a městské muzeum světoznámé halštatské nálezy — kraj byl před třemi tisíci lety centrem doby železné. Živé kavárny zvou k pauze nad řekou.', 45.8036, 15.1689, 'https://commons.wikimedia.org/wiki/Special:FilePath/Novo%20mesto.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Novo%20mesto.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Glavni%20trg,%20Novo%20mesto.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Gostišče Loka (Novo mesto)', 'Výborně hodnocená restaurace na břehu Krky pod Hlavním náměstím, s terasou přímo u vody a výhledem na staré město. Nabízí dolenjskou kuchyni i moderní jídla, čerstvé ryby a k tomu sklenku cvičku pro spolujezdce. V létě je terasa nad řekou nejpříjemnějším místem ve městě.', 45.8022, 15.1697, 'https://commons.wikimedia.org/wiki/Special:FilePath/Novo%20mesto.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Novo%20mesto.jpg"}'::text[], 3),
    (v_route, 'Hrad Otočec', 'Jediný vodní hrad ve Slovinsku stojí na ostrůvku uprostřed Krky a s cimbuřím zrcadlícím se v hladině vypadá jako z pohádky. Dnes v něm sídlí zámecký hotel, ale přes mostky se dá projít na nádvoří a kolem ostrova vede příjemná procházka. Jedno z nejromantičtějších zastavení trasy.', 45.8386, 15.2247, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oto%C4%8Dec%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oto%C4%8Dec%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Oto%C4%8Dec.jpg"}'::text[], 4),
    (v_route, 'Kartuziánský klášter Pleterje', 'Jediná dosud živá kartouza ve Slovinsku leží v tichém údolí pod Gorjanci — mniši žijí v přísném mlčení, návštěvníkům je přístupný gotický kostel a multivize o životě řádu. U kláštera koupíte proslulou hruškovici z hrušek pěstovaných přímo v lahvích a vedle stojí skanzen dolenjského statku. Místo, kde se čas zastavil.', 45.8206, 15.3372, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kartuzija%20Pleterje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kartuzija%20Pleterje.jpg"}'::text[], 5),
    (v_route, 'Kostanjevica na Krki', 'Nejmenší slovinské město leží celé na říčním ostrově obtékaném Krkou — dva mostky, dvě ulice a atmosféra, které místní říkají dolenjské Benátky. V bývalém cisterciáckém klášteře sídlí galerie Božidar Jakac s největší sbírkou umění v zemi a nádherným arkádovým nádvořím. Půvabná tečka za trasou údolím Krky.', 45.8461, 15.4231, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kostanjevica%20na%20Krki.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kostanjevica%20na%20Krki.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Idrija – rtuťový důl UNESCO', 'Pět set let se tu těžila rtuť a idrijský důl, druhý největší na světě, je dnes součástí světového dědictví UNESCO. Štola Antonijev rov vás zavede přímo do podzemí mezi kapky ryzí rtuti ve skále. Město proslavila i paličkovaná krajka — idrijská čipka — a knedlíčky žlikrofi, první slovinské jídlo s chráněným označením.', 46.0022, 14.0272, 'https://commons.wikimedia.org/wiki/Special:FilePath/Idrija.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Idrija.jpg"}'::text[], 0),
    (v_route, 'Hrad Gewerkenegg', 'Renesanční hrad nad Idrijí nechali v 16. století postavit správci rtuťového dolu jako sídlo a sklad — dnes v něm sídlí městské muzeum s expozicemi o rtuti, krajce a dějinách hornického města. Arkádové nádvoří s freskami patří k nejhezčím ve Slovinsku. Od hradu je pěkný výhled na střechy Idrije.', 46.0031, 14.0253, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Gewerkenegg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grad%20Gewerkenegg.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Gostilna Pri Škafarju (Idrija)', 'Tradiční rodinná gostilna v centru Idrije, nejlepší adresa na ochutnání pravých idrijských žlikrofů — bramborových knedlíčků s tvarem třírohého klobouku, servírovaných se skopovou omáčkou bakalca. Poctivá domácí kuchyně a přátelské ceny z ní dělají ideální obědovou zastávku okruhu.', 46.0017, 14.0281, 'https://commons.wikimedia.org/wiki/Special:FilePath/Idrija.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Idrija.jpg"}'::text[], 2),
    (v_route, 'Divje jezero', 'Divoké jezero pod kolmou skalní stěnou je zatopená krasová jeskyně, z níž po deštích vyvěrá voda takovou silou, že hladina doslova kypí — potápěči v sifonu dosáhli hloubky přes 160 metrů a dna nedosáhli. Smaragdová hladina obklopená stěnami působí až tajemně. Od parkoviště u silnice je to k jezeru pár minut po naučné stezce.', 45.9906, 14.0189, 'https://commons.wikimedia.org/wiki/Special:FilePath/Divje%20jezero.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Divje%20jezero.jpg"}'::text[], 3),
    (v_route, 'Cerkno', 'Městečko v kotlině pod lyžařským střediskem je známé masopustními maskami laufarji s dřevěnými obličeji, které vystavuje místní muzeum. Okolí nabízí hustou síť klikatých silniček — sem se sjíždějí slovinští motorkáři trénovat zatáčky. Příjemná kávová pauza před závěrečnou etapou.', 46.1253, 13.9814, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerkno.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerkno.jpg"}'::text[], 4),
    (v_route, 'Partyzánská nemocnice Franja', 'V těsné soutěsce Pasice u Cerkna se za druhé světové války skrývala tajná partyzánská nemocnice — dřevěné baráky u potoka, kam raněné nosili se zavázanýma očima, ošetřily přes pět set vojáků a Němci ji nikdy neobjevili. Dnes je památkou pod ochranou UNESCO se vstupem po lávkách soutěskou. Silné místo, které bere dech i bez motorky.', 46.1461, 14.0072, 'https://commons.wikimedia.org/wiki/Special:FilePath/Partizanska%20bolnica%20Franja.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Partizanska%20bolnica%20Franja.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Franja%20Partisan%20Hospital.jpg"}'::text[], 5),
    (v_route, 'Žiri', 'Městečko na rozhraní tří slovinských regionů, proslulé výrobou obuvi a paličkované krajky — místní krajkářská škola patří k nejstarším v zemi. Okolní kopce nabízejí poslední porci zatáček před návratem do Logatce. V muzeu Žiri si prohlédnete, jak se z malé vsi stalo centrum ševcovského řemesla.', 46.0442, 14.1097, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDiri.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDiri.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Celjský hrad (Stari grad)', 'Největší středověký hrad ve Slovinsku, sídlo mocných Celjských hrabat, jejichž tři hvězdy dodnes září ve slovinském státním znaku. Z Friedrichovy věže se otevírá výhled na město, meandr Savinje a při dobré viditelnosti až ke Kamnicko-Savinjským Alpám. Na hrad vede pěkná krátká silnička — ideální rozjezd okruhu.', 46.2197, 15.2753, 'https://commons.wikimedia.org/wiki/Special:FilePath/Celje%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Celje%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stari%20grad%20Celje.jpg"}'::text[], 0),
    (v_route, 'Laško', 'Lázeňské městečko sevřené v údolí Savinje žije pivem a včelami — pivovar Laško tu vaří zlatorog od roku 1825 a ochutnávku nabízí návštěvnické centrum. Nad městečkem stojí hrad Tabor, u řeky termální lázně. Silnice z Celje do Laška soutěskou podél řeky a železnice je nejhezčí úsek okruhu.', 46.1544, 15.2364, 'https://commons.wikimedia.org/wiki/Special:FilePath/La%C5%A1ko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/La%C5%A1ko.jpg"}'::text[], 1),
    (v_route, 'Římská nekropole Šempeter', 'Nejvýznamnější římská památka ve Slovinsku — pohřebiště zámožných rodin antické Celeie s monumentálními mramorovými hrobkami zdobenými reliéfy bájí a výjevů z každodenního života. Náhrobky vysoké až osm metrů stojí v upraveném parku přímo u silnice. Krátká, ale působivá cesta o dva tisíce let zpět.', 46.2564, 15.1214, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rimska%20nekropola%20%C5%A0empeter.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rimska%20nekropola%20%C5%A0empeter.jpg"}'::text[], 2),
    (v_route, 'Žalec – Fontána piv', 'Hlavní město slovinského chmelařství postavilo světový unikát — veřejnou fontánu Zeleno zlato, z níž si do zálohované sklenice natočíte šest druhů piv z místního chmele. Kolem městečka se táhnou chmelnice, jejich příběh vypráví Ekomuzeum chmelařství. Řidič degustaci pochopitelně odloží, spolujezdec si ji užije za oba.', 46.2514, 15.1647, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fontana%20piv%20Zeleno%20zlato.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fontana%20piv%20Zeleno%20zlato.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDalec.jpg"}'::text[], 3),
    (v_route, 'Šmartinsko jezero', 'Jedno z největších umělých jezer ve Slovinsku s členitými zátokami a zalesněnými břehy leží jen pár kilometrů od centra Celje. Kolem hladiny vede okružní stezka, na břehu jsou pláže, půjčovny lodiček a příjemné kavárny s terasou nad vodou. Klidná předposlední zastávka před návratem do města.', 46.2708, 15.2469, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0martinsko%20jezero.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0martinsko%20jezero.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Stari Pisker (Celje)', 'Legendární grilovna ve starém vězení v centru Celje, dlouhodobě jedna z nejlépe hodnocených restaurací ve městě. Servírují vyzrálé steaky, žebra a burgery z lokálního masa; interiér s cihlovými klenbami má nezaměnitelnou atmosféru. Po okruhu údolím Savinje ideální místo na vydatnou večeři — v pátek a v sobotu rezervujte.', 46.2297, 15.2611, 'https://commons.wikimedia.org/wiki/Special:FilePath/Celje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Celje.jpg"}'::text[], 5);
